// scene3d/film/runtime/lens_overlay.js — FPV props in front of the lens (Egg Orchard DESIGN §3, `?filmProps=on`).
//
// WHY: real FPV footage is recognised by its hard-mounted, up-tilted camera AND by
// the two front propellers spinning at the top corners of the frame. Those props
// sit a few centimetres in front of the lens: no depth of field, bloom, grade,
// fog or tone curve of the world touches them, and they never move relative to
// the frame (hard mount). So they are NOT world geometry: this module owns a
// separate three.js Scene + PerspectiveCamera (the film fov / canvas aspect) and
// draws it straight into the default framebuffer AFTER the composer — the take
// player calls draw() inside its postRender grab listener immediately BEFORE
// `recorder.grab` (same task), so every recorded frame carries the props and the
// post chain never sees them.
//
// What is drawn (procedural, no assets; every texture is generated by a pure pixel
// function into a DataTexture, deterministic):
//   * 'freestyle' — two 5" tri-blade props at the top-left / top-right corners,
//     partly out of frame, each a soft motion-blurred disc + faint blade ghosts
//     (each blade drawn 3× along its angular smear) + the motor bell, and a faint
//     carbon arm stub running from the motor out of the frame side;
//   * 'cinewhoop' — smaller 5-blade props inside ducts whose rims show at the
//     top edge (an upper and a lower lip).
// The discs lie in the craft's horizontal plane, seen from below through the
// camera uptilt (`uptiltDeg`), placed by NDC so they sit at the same frame
// position at any fov / aspect. Spin: blade angle = 2π·(f0·t + f1·Θ) with t the
// FILM time of the frame and Θ = ∫ throttle dt (the caller's throttle integral;
// for a constant throttle this is exactly 2π·(f0 + f1·throttle)·t) — an apparent
// (aliased) rotation rate, pure in its inputs, so stepped and realtime takes give
// the same angle at the same film time. The throttle (thrust / weight, |a + g ẑ|/g:
// 1 = hover, 0 = free fall, ≈2–2.5 = full punch) also mixes the look: a chop shows
// crisper, slower blades (ghosts up, disc down), a punch a denser blur disc.
// NOTHING imitates a video link: no noise, static, scanlines, breakup or colour bleed.
//
// Renderer state: autoClear, the render target and `info.autoReset` are saved and
// restored around the one render() call (the overlay adds its few draw calls to
// the frame's renderer.info instead of zeroing it). Materials are MeshBasic,
// transparent, depthTest / depthWrite off, fog off, toneMapped off.
//
// Film mode is DEFAULT OFF (`?filmMode=on`); the overlay draws only with
// `?filmProps=on` AND a shot `overlay.props` (take_player gates it). Page module:
// THREE and the renderer are injected; no stateful imports, no clocks, no random.

/** Overlay styles. */
export const LENS_OVERLAY_STYLES = Object.freeze(["freestyle", "cinewhoop"]);

/**
 * Apparent (aliased) spin: revolutions per second at zero throttle (f0) and per unit of
 * throttle (f1). Real props turn at 300–600 rev/s; sampled at 24–60 fps only this slow
 * apparent drift of the blade pattern is visible.
 */
export const LENS_OVERLAY_SPIN = Object.freeze({ f0: 0.35, f1: 0.9 });

/**
 * Throttle → look: `mix` = clamp(throttle / maxThrottle, 0, 1) blends each pair
 * [chop (free fall), full punch]. A chop shows crisp blades (ghosts up, short
 * smear, faint disc); a punch a dense blur disc with faint, long-smeared ghosts.
 */
export const LENS_OVERLAY_LOOK = Object.freeze({
  maxThrottle: 2.5,
  discOpacity: Object.freeze([0.22, 0.52]),
  ghostOpacity: Object.freeze([0.42, 0.12]),
  smearRad: Object.freeze([0.18, 0.75]),
  ghostsPerBlade: 3,
  hubOpacity: 0.9,
  armOpacity: 0.55,
  ductOpacity: 0.85,
});

/**
 * Per-style layout (NDC of the hub — x mirrored per side, y up; radius as a fraction of
 * the frame's half-height at the hub depth), blades, default tint and uptilt.
 */
export const LENS_OVERLAY_LAYOUTS = Object.freeze({
  freestyle: Object.freeze({
    hubNdc: Object.freeze([0.9, 1.0]),
    radius: 0.6,
    blades: 3,
    tint: "#3b3f46",
    uptiltDeg: 25,
    arm: Object.freeze({ lengthR: 1.5, widthR: 0.16, dropR: 0.14, dirX: 0.59, dirZ: 0.81 }),
    duct: null,
  }),
  cinewhoop: Object.freeze({
    hubNdc: Object.freeze([0.74, 1.12]),
    radius: 0.42,
    blades: 5,
    tint: "#33363c",
    uptiltDeg: 15,
    arm: null,
    duct: Object.freeze({ radiusR: 1.24, lipDropR: 0.26 }),
  }),
});

/** Colours of the parts that are not the prop itself (sRGB hex). */
const PART_COLORS = Object.freeze({ hub: "#26282c", arm: "#1d1e21", duct: "#2a2b2e", ductLow: "#1f2023" });

/** Hub depth (overlay camera units: only ratios matter). */
const HUB_DEPTH = 1;
/** A disc / duct never reaches closer to the lens than this fraction of the hub depth. */
const MIN_DEPTH_FRAC = 0.22;
/** Texture edge (px) of the generated textures. */
const TEX = 128;
/** Right prop phase offset (revolutions) — the two props are never mirror-synchronised. */
const RIGHT_PHASE_REV = 0.21;

// ---------------------------------------------------------------------------
// pure helpers
// ---------------------------------------------------------------------------

function fin(v, d) {
  return typeof v === "number" && Number.isFinite(v) ? v : d;
}

function clamp(x, lo, hi) {
  return x < lo ? lo : x > hi ? hi : x;
}

/** Smoothstep on [0, 1] (clamped). */
function smooth01(x) {
  const t = clamp(x, 0, 1);
  return t * t * (3 - 2 * t);
}

function lerp(a, b, w) {
  return a + (b - a) * w;
}

/**
 * A shot's `overlay` (plan `shot.overlay` → `take.overlay`) normalised: `{props: {style,
 * opacity, tint}}` with a known style, opacity in [0, 1] (default 1) and a `#rrggbb`
 * tint (default: the style's), or null when it asks for no props. Unknown keys are
 * ignored here (the plan validator warns about them).
 * @param {*} raw
 * @returns {{props:{style:string, opacity:number, tint:string}}|null}
 */
export function normalizeOverlay(raw) {
  const o = raw && typeof raw === "object" && !Array.isArray(raw) ? raw : null;
  const p = o && o.props && typeof o.props === "object" && !Array.isArray(o.props) ? o.props : null;
  if (!p) return null;
  const style = LENS_OVERLAY_STYLES.includes(p.style) ? p.style : null;
  if (!style) return null;
  const opacity = Number.isFinite(p.opacity) ? clamp(p.opacity, 0, 1) : 1;
  const tint = typeof p.tint === "string" && /^#[0-9a-fA-F]{6}$/.test(p.tint) ? p.tint.toLowerCase() : LENS_OVERLAY_LAYOUTS[style].tint;
  return { props: { style, opacity, tint } };
}

/**
 * Prop phase in REVOLUTIONS at film time `t` with throttle integral `theta` (throttle·s):
 * f0·t + f1·θ. Pure. For a constant throttle k (θ = k·t) the angle is 2π·(f0 + f1·k)·t.
 * @param {number} t film time (s)
 * @param {number} theta ∫ throttle dt over the take
 * @param {{f0:number, f1:number}} [spin]
 * @returns {number}
 */
export function propsPhase(t, theta, spin = LENS_OVERLAY_SPIN) {
  return fin(spin.f0, LENS_OVERLAY_SPIN.f0) * fin(t, 0) + fin(spin.f1, LENS_OVERLAY_SPIN.f1) * fin(theta, 0);
}

/**
 * The throttle-dependent look (LENS_OVERLAY_LOOK): `{mix, discOpacity, ghostOpacity, smearRad}`.
 * @param {number} throttle thrust / weight (1 = hover)
 * @returns {{mix:number, discOpacity:number, ghostOpacity:number, smearRad:number}}
 */
export function propsLook(throttle) {
  const L = LENS_OVERLAY_LOOK;
  const mix = clamp(fin(throttle, 1) / L.maxThrottle, 0, 1);
  return {
    mix,
    discOpacity: lerp(L.discOpacity[0], L.discOpacity[1], mix),
    ghostOpacity: lerp(L.ghostOpacity[0], L.ghostOpacity[1], mix),
    smearRad: lerp(L.smearRad[0], L.smearRad[1], mix),
  };
}

/**
 * Camera-space layout of the props for a style at a vertical fov / aspect (three camera
 * frame: x right, y up, −z forward; the hub at depth HUB_DEPTH): per prop `{side, hub,
 * radius, ductRadius, hubNdc}` plus the prop plane tilt `uptiltRad` (the disc normal is the
 * craft's up: (0, cos u, −sin u)). The radius is clamped so no disc / duct reaches behind
 * MIN_DEPTH_FRAC of the hub depth (very wide fovs).
 * @param {string} style
 * @param {number} fovDeg vertical fov
 * @param {number} aspect width / height
 * @param {number} [uptiltDeg] default: the style's
 * @returns {{style:string, uptiltRad:number, blades:number, props:Array<{side:number, hub:number[], radius:number, ductRadius:number|null, hubNdc:number[]}>}}
 */
export function propsLayout(style, fovDeg, aspect, uptiltDeg) {
  const S = LENS_OVERLAY_LAYOUTS[style] || LENS_OVERLAY_LAYOUTS.freestyle;
  const fov = clamp(fin(fovDeg, 90), 10, 160);
  const asp = fin(aspect, 16 / 9) > 0 ? fin(aspect, 16 / 9) : 16 / 9;
  const u = (clamp(fin(uptiltDeg, S.uptiltDeg), 0, 60) * Math.PI) / 180;
  const tanH = Math.tan((fov * Math.PI) / 360);
  const d = HUB_DEPTH;
  // Reach toward the lens of a disc of radius r tilted by u: r·cos u (its near rim).
  const maxReach = (1 - MIN_DEPTH_FRAC) * d;
  const ductK = S.duct ? S.duct.radiusR : 1;
  let radius = S.radius * tanH * d;
  if (radius * ductK * Math.cos(u) > maxReach) radius = maxReach / (ductK * Math.cos(u));
  const props = [-1, 1].map((side) => {
    const nx = side * S.hubNdc[0];
    const ny = S.hubNdc[1];
    return {
      side,
      hub: [nx * tanH * asp * d, ny * tanH * d, -d],
      radius,
      ductRadius: S.duct ? radius * S.duct.radiusR : null,
      hubNdc: [nx, ny],
    };
  });
  return { style: LENS_OVERLAY_LAYOUTS[style] ? style : "freestyle", uptiltRad: u, blades: S.blades, props };
}

// ---------------------------------------------------------------------------
// procedural textures (pure pixel functions; RGBA8, white-ish luminance × alpha)
// ---------------------------------------------------------------------------

/** Motion-blurred prop disc: transparent hub hole, denser band where the blades are widest, soft rim. */
function discPixel(x, y) {
  const rho = Math.hypot(x, y);
  if (rho >= 1) return [0, 0];
  const inner = smooth01((rho - 0.1) / 0.1);
  const outer = 1 - smooth01((rho - 0.86) / 0.13);
  const band = 0.6 + 0.4 * Math.exp(-(((rho - 0.7) / 0.17) ** 2));
  const lum = 0.82 + 0.18 * smooth01((rho - 0.75) / 0.2); // a lighter tip ring
  return [lum, inner * outer * band];
}

/** One swept, tapered blade along +x (its root near the hub, a rounded tip at ρ ≈ 0.97). */
function bladePixel(x, y) {
  if (x < 0.06 || x > 1) return [0, 0];
  const s = clamp((x - 0.1) / 0.87, 0, 1);
  const half = 0.02 + 0.1 * Math.pow(Math.sin(Math.PI * Math.min(1, s * 1.08)), 0.6);
  const yc = 0.07 * x * x; // swept back
  const edge = 1 - smooth01((Math.abs(y - yc) - half) / 0.03 + 0.5);
  const root = smooth01((x - 0.06) / 0.06);
  const tip = 1 - smooth01((x - 0.95) / 0.04);
  return [0.9 + 0.1 * (1 - s), edge * root * tip];
}

/** Motor bell: a solid disc with a lighter rim ring and a soft edge. */
function hubPixel(x, y) {
  const rho = Math.hypot(x, y);
  const a = 1 - smooth01((rho - 0.82) / 0.14);
  const lum = 0.55 + 0.45 * smooth01((rho - 0.45) / 0.12) * (1 - smooth01((rho - 0.7) / 0.1));
  return [lum, a];
}

/** Duct rim seen from below: an annulus, lighter at the inner lip. */
function ringPixel(x, y) {
  const rho = Math.hypot(x, y);
  const a = smooth01((rho - 0.8) / 0.03) * (1 - smooth01((rho - 0.96) / 0.03));
  const lum = 1 - 0.4 * smooth01((rho - 0.82) / 0.14);
  return [lum, a];
}

/** Arm stub (u along the arm from the motor, v across): soft edges, a lengthwise sheen, fading out. */
function armPixel(u, v) {
  const across = 1 - smooth01((Math.abs(v) - 0.7) / 0.25);
  const along = smooth01(u / 0.08) * (1 - smooth01((u - 0.55) / 0.45));
  const lum = 0.72 + 0.28 * Math.exp(-(((v + 0.3) / 0.25) ** 2));
  return [lum, across * along];
}

/**
 * RGBA8 pixels of a pixel function over a w×h texture. Square textures map pixel centres
 * to [−1, 1]² (x right, y up); the arm maps u ∈ [0, 1] along x and v ∈ [−1, 1] across.
 * @returns {Uint8Array}
 */
export function bakePixels(fn, w = TEX, h = TEX, mode = "square") {
  const data = new Uint8Array(w * h * 4);
  for (let j = 0; j < h; j += 1) {
    for (let i = 0; i < w; i += 1) {
      const a = mode === "strip" ? (i + 0.5) / w : ((i + 0.5) / w) * 2 - 1;
      const b = ((j + 0.5) / h) * 2 - 1;
      const [lum, alpha] = fn(a, b);
      const o = (j * w + i) * 4;
      const l = Math.round(clamp(lum, 0, 1) * 255);
      data[o] = l;
      data[o + 1] = l;
      data[o + 2] = l;
      data[o + 3] = Math.round(clamp(alpha, 0, 1) * 255);
    }
  }
  return data;
}

// ---------------------------------------------------------------------------
// the overlay
// ---------------------------------------------------------------------------

/**
 * Create the lens overlay (page side; THREE and the renderer injected).
 *
 * - `configure(overlay, {uptiltDeg})` → `{ok, on, style, reason?}`: `overlay` = a take's
 *   `overlay` (normalizeOverlay); builds the style's props scene once (rebuilt on a style
 *   change), applies tint / opacity; null / no props → off.
 * - `draw({t, theta?, throttle, fov, aspect?})` → `{drawn, phaseRev, angles, look}`: renders
 *   the props into the default framebuffer over the finished frame (call it right before
 *   the recorder grabs), renderer state restored. `theta` defaults to throttle·t; the
 *   aspect is the canvas's (renderer.domElement), else `aspect`, else 16/9.
 * - `active`, `style`, `stats()`, `dispose()`.
 * @param {{THREE:object, renderer:object, log?:(entry:object)=>void}} deps
 * @returns {object}
 */
export function createLensOverlay(deps = {}) {
  const d = deps && typeof deps === "object" ? deps : {};
  const T = d.THREE && typeof d.THREE === "object" ? d.THREE : null;
  const renderer = d.renderer && typeof d.renderer === "object" ? d.renderer : null;
  const emit = (entry) => {
    if (typeof d.log !== "function") return;
    try {
      d.log({ event: "film-lens-overlay", ...entry });
    } catch (_) {
      /* a logger never breaks a frame */
    }
  };
  const usable = !!(T && ["Scene", "PerspectiveCamera", "Group", "Mesh", "PlaneGeometry", "MeshBasicMaterial", "DataTexture"].every((k) => typeof T[k] === "function") &&
    renderer && typeof renderer.render === "function");

  const state = {
    built: null, // {style, scene, camera, props:[…], disposables:[…]}
    cfg: null, // normalized overlay props
    uptiltDeg: null,
    layoutKey: null,
  };
  const counters = { configures: 0, draws: 0, errors: 0, builds: 0 };
  const textures = {};

  function texture(name, fn, w, h, mode) {
    if (textures[name]) return textures[name];
    const data = bakePixels(fn, w, h, mode);
    const tex = new T.DataTexture(data, w, h, T.RGBAFormat);
    if (T.LinearFilter !== undefined) {
      tex.magFilter = T.LinearFilter;
      tex.minFilter = T.LinearFilter;
    }
    tex.generateMipmaps = false;
    if (T.SRGBColorSpace !== undefined) tex.colorSpace = T.SRGBColorSpace;
    tex.needsUpdate = true;
    textures[name] = tex;
    return tex;
  }

  function material(map, color) {
    return new T.MeshBasicMaterial({
      map,
      color,
      transparent: true,
      opacity: 1,
      depthTest: false,
      depthWrite: false,
      fog: false,
      toneMapped: false,
      side: T.DoubleSide !== undefined ? T.DoubleSide : 2,
    });
  }

  /** A unit quad lying in the parent's XZ plane (normal +Y), scaled to `sx` × `sz`. */
  function flatQuad(geo, mat, sx, sz, order) {
    const mesh = new T.Mesh(geo, mat);
    mesh.rotation.x = -Math.PI / 2;
    mesh.scale.set(sx, sz, 1);
    mesh.renderOrder = order;
    mesh.frustumCulled = false;
    return mesh;
  }

  /** Build the scene graph of a style (unit-radius props, placed per frame). */
  function build(style) {
    const S = LENS_OVERLAY_LAYOUTS[style];
    const scene = new T.Scene();
    const camera = new T.PerspectiveCamera(90, 16 / 9, 0.005, 20);
    const geo = new T.PlaneGeometry(1, 1);
    const disposables = [geo];
    const own = (m) => {
      disposables.push(m);
      return m;
    };
    const tDisc = texture("disc", discPixel, TEX, TEX, "square");
    const tBlade = texture("blade", bladePixel, TEX, TEX, "square");
    const tHub = texture("hub", hubPixel, 64, 64, "square");
    const tRing = S.duct ? texture("ring", ringPixel, TEX, TEX, "square") : null;
    const tArm = S.arm ? texture("arm", armPixel, TEX, 32, "strip") : null;
    const props = [];
    for (const side of [-1, 1]) {
      const group = new T.Group();
      // Disc (unit radius → a 2×2 quad).
      const discMat = own(material(tDisc, 0xffffff));
      const disc = flatQuad(geo, discMat, 2, 2, 1);
      group.add(disc);
      // Blade ghosts: one spinner per prop, `blades` blades × ghostsPerBlade copies.
      const spinner = new T.Group();
      const ghosts = [];
      for (let b = 0; b < S.blades; b += 1) {
        for (let g = 0; g < LENS_OVERLAY_LOOK.ghostsPerBlade; g += 1) {
          const holder = new T.Group();
          const mat = own(material(tBlade, 0xffffff));
          holder.add(flatQuad(geo, mat, 2, 2, 2));
          spinner.add(holder);
          ghosts.push({ holder, mat, blade: b, ghost: g });
        }
      }
      group.add(spinner);
      // Motor bell.
      const hubMat = own(material(tHub, PART_COLORS.hub));
      const hub = flatQuad(geo, hubMat, 0.3, 0.3, 3);
      hub.position.y = -0.02;
      group.add(hub);
      // Arm stub (freestyle): from the motor toward the frame side, under the prop plane.
      let arm = null;
      let armMat = null;
      if (S.arm) {
        const holder = new T.Group();
        armMat = own(material(tArm, PART_COLORS.arm));
        const q = flatQuad(geo, armMat, S.arm.lengthR, S.arm.widthR, 4);
        q.position.x = S.arm.lengthR / 2;
        holder.add(q);
        // Local +x of the holder → (−side·dirX, 0, +dirZ): toward the craft centre, behind the motor.
        holder.rotation.y = -Math.atan2(S.arm.dirZ, -side * S.arm.dirX);
        holder.position.y = -S.arm.dropR;
        group.add(holder);
        arm = holder;
      }
      // Duct lips (cinewhoop): an upper rim at the prop plane and a darker lower one.
      const ducts = [];
      if (S.duct) {
        for (const [drop, color, order] of [[0, PART_COLORS.duct, 6], [S.duct.lipDropR, PART_COLORS.ductLow, 5]]) {
          const mat = own(material(tRing, color));
          const ring = flatQuad(geo, mat, 2 * S.duct.radiusR, 2 * S.duct.radiusR, order);
          ring.position.y = -drop;
          group.add(ring);
          ducts.push({ ring, mat });
        }
      }
      scene.add(group);
      props.push({ side, group, disc, discMat, spinner, ghosts, hub, hubMat, arm, armMat, ducts });
    }
    counters.builds += 1;
    return { style, scene, camera, props, disposables, blades: S.blades };
  }

  function disposeBuilt() {
    const b = state.built;
    state.built = null;
    state.layoutKey = null;
    if (!b) return;
    for (const x of b.disposables) {
      try {
        if (x && typeof x.dispose === "function") x.dispose();
      } catch (_) {
        /* best effort */
      }
    }
  }

  /** Apply the shot's tint / opacity to the built materials (per-frame opacities are set by draw). */
  function applyColors() {
    const b = state.built;
    if (!b || !state.cfg) return;
    for (const p of b.props) {
      setColor(p.discMat, state.cfg.tint);
      for (const g of p.ghosts) setColor(g.mat, state.cfg.tint);
    }
  }

  function setColor(mat, hex) {
    if (mat && mat.color && typeof mat.color.set === "function") mat.color.set(hex);
  }

  function configure(overlay, opts = {}) {
    counters.configures += 1;
    const n = normalizeOverlay(overlay);
    if (!n) {
      state.cfg = null;
      return { ok: true, on: false, style: null, reason: "the shot has no overlay.props" };
    }
    if (!usable) {
      state.cfg = null;
      return { ok: false, on: false, style: n.props.style, reason: "no THREE / renderer to draw the overlay with" };
    }
    try {
      if (!state.built || state.built.style !== n.props.style) {
        disposeBuilt();
        state.built = build(n.props.style);
      }
    } catch (e) {
      counters.errors += 1;
      disposeBuilt();
      state.cfg = null;
      emit({ level: "warn", message: `building the props overlay failed: ${e && e.message ? e.message : e}` });
      return { ok: false, on: false, style: n.props.style, reason: `build failed: ${e && e.message ? e.message : e}` };
    }
    state.cfg = n.props;
    const up = opts && Number.isFinite(opts.uptiltDeg) ? opts.uptiltDeg : null;
    state.uptiltDeg = up;
    state.layoutKey = null;
    applyColors();
    return { ok: true, on: true, style: n.props.style };
  }

  function canvasAspect() {
    const el = renderer && renderer.domElement;
    const w = el ? Number(el.width) : NaN;
    const h = el ? Number(el.height) : NaN;
    return Number.isFinite(w) && Number.isFinite(h) && w > 0 && h > 0 ? w / h : null;
  }

  /** Place the props for this fov / aspect (only when they changed). */
  function place(fov, aspect) {
    const b = state.built;
    const key = `${fov}|${aspect}|${state.uptiltDeg}`;
    if (state.layoutKey === key) return;
    const L = propsLayout(b.style, fov, aspect, state.uptiltDeg ?? undefined);
    b.camera.fov = clamp(fov, 10, 160);
    b.camera.aspect = aspect;
    if (typeof b.camera.updateProjectionMatrix === "function") b.camera.updateProjectionMatrix();
    const S = LENS_OVERLAY_LAYOUTS[b.style];
    for (let i = 0; i < b.props.length; i += 1) {
      const p = b.props[i];
      const l = L.props[i];
      p.group.position.set(l.hub[0], l.hub[1], l.hub[2]);
      p.group.rotation.set(-L.uptiltRad, 0, 0);
      p.group.scale.set(l.radius, l.radius, l.radius);
      if (p.arm && S.arm) {
        // The stub runs toward the lens: shorten it so its end stays ≥ MIN_DEPTH_FRAC of the hub depth away.
        const reach = l.radius * S.arm.lengthR * S.arm.dirZ * Math.cos(L.uptiltRad);
        const k = reach > 0 ? Math.min(1, ((1 - MIN_DEPTH_FRAC) * HUB_DEPTH) / reach) : 1;
        p.arm.scale.set(k, 1, 1);
      }
    }
    state.layoutKey = key;
  }

  /**
   * Draw the props over the finished frame (default framebuffer), renderer state restored.
   * @param {{t:number, theta?:number, throttle?:number, fov?:number, aspect?:number}} f
   */
  function draw(f = {}) {
    const b = state.built;
    if (!state.cfg || !b || !usable) return { drawn: false, phaseRev: null, angles: null, look: null };
    const t = fin(f.t, 0);
    const throttle = clamp(fin(f.throttle, 1), 0, 4);
    const theta = Number.isFinite(f.theta) ? f.theta : throttle * t;
    const fov = clamp(fin(f.fov, 90), 10, 160);
    const aspect = canvasAspect() ?? (fin(f.aspect, 0) > 0 ? f.aspect : 16 / 9);
    const look = propsLook(throttle);
    const phaseRev = propsPhase(t, theta);
    const op = state.cfg.opacity;
    const L = LENS_OVERLAY_LOOK;
    const angles = [];
    place(fov, aspect);
    for (const p of b.props) {
      const rev = p.side < 0 ? phaseRev : -(phaseRev + RIGHT_PHASE_REV);
      const base = 2 * Math.PI * (rev - Math.floor(rev));
      angles.push(base);
      p.spinner.rotation.y = base;
      p.discMat.opacity = look.discOpacity * op;
      p.hubMat.opacity = L.hubOpacity * op;
      if (p.armMat) p.armMat.opacity = L.armOpacity * op;
      for (const du of p.ducts) du.mat.opacity = L.ductOpacity * op;
      const n = L.ghostsPerBlade;
      const dir = p.side < 0 ? 1 : -1; // ghosts trail behind the spin
      for (const g of p.ghosts) {
        const w = n > 1 ? g.ghost / (n - 1) : 0;
        g.holder.rotation.y = (2 * Math.PI * g.blade) / b.blades - dir * w * look.smearRad;
        g.mat.opacity = look.ghostOpacity * (1 - 0.6 * w) * op;
      }
    }
    const r = renderer;
    const saved = {
      autoClear: r.autoClear,
      target: typeof r.getRenderTarget === "function" ? r.getRenderTarget() : null,
      infoAutoReset: r.info && typeof r.info.autoReset === "boolean" ? r.info.autoReset : undefined,
    };
    let drawn = false;
    try {
      if (saved.target !== null && typeof r.setRenderTarget === "function") r.setRenderTarget(null);
      r.autoClear = false;
      if (saved.infoAutoReset !== undefined) r.info.autoReset = false;
      r.render(b.scene, b.camera);
      drawn = true;
      counters.draws += 1;
    } catch (e) {
      counters.errors += 1;
      if (counters.errors <= 3) emit({ level: "warn", message: `props overlay draw failed: ${e && e.message ? e.message : e}` });
    } finally {
      r.autoClear = saved.autoClear;
      if (saved.infoAutoReset !== undefined) r.info.autoReset = saved.infoAutoReset;
      if (saved.target !== null && typeof r.setRenderTarget === "function") r.setRenderTarget(saved.target);
    }
    return { drawn, phaseRev, angles, look };
  }

  function dispose() {
    disposeBuilt();
    for (const k of Object.keys(textures)) {
      try {
        textures[k].dispose();
      } catch (_) {
        /* best effort */
      }
      delete textures[k];
    }
    state.cfg = null;
  }

  return {
    configure,
    draw,
    dispose,
    get active() {
      return !!(state.cfg && state.built && usable);
    },
    get style() {
      return state.cfg ? state.cfg.style : null;
    },
    /** The built scene graph (tests / diagnostics). */
    scene: () => (state.built ? state.built.scene : null),
    stats: () => ({ ...counters, usable, style: state.cfg ? state.cfg.style : null, built: state.built ? state.built.style : null }),
  };
}
